BASE = "/workspace/notebooks/llama.cpp-ph2/ggml/src/ggml-cuda8"
BACKEND_H = os.path.join(BASE, "ggml-cuda8-ggml-backend.h")
BACKEND_CPP = os.path.join(BASE, "ggml-cuda8-ggml-backend.cpp")
PROBE_CPP = os.path.join(BASE, "ggml-cuda8-ggml-backend-graph-api-probe.cpp")
CMAKE = os.path.join(BASE, "CMakeLists.txt")
BACKEND_H_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend.h\n//\n// G12A/G13A/G14B: minimal ggml_backend_t wrapper/probe for CUDA8.\n\n#ifndef GGML_CUDA8_GGML_BACKEND_H\n#define GGML_CUDA8_GGML_BACKEND_H\n\n#include "ggml-backend.h"\n#include "ggml-cuda8-dispatch.h"\n\n#ifdef __cplusplus\nextern "C" {\n#endif\n\nggml_backend_t ggml_cuda8_ggml_backend_init(int device);\nint ggml_cuda8_ggml_backend_is_cuda8(ggml_backend_t backend);\nggml_backend_buffer_type_t ggml_cuda8_ggml_backend_get_default_buffer_type(ggml_backend_t backend);\n\n// G13A/G13B: compute-shaped helper used by backend-owned smoke graphs.\n// This helper is intentionally separate from ggml_backend_i graph_compute.\nint ggml_cuda8_ggml_backend_dispatch_op(\n    ggml_backend_t backend,\n    ggml_cuda8_context * ctx,\n    int op,\n    const ggml_tensor * src0,\n    const ggml_tensor * src1,\n    ggml_tensor * dst\n);\n\n#ifdef __cplusplus\n}\n#endif\n\n#endif // GGML_CUDA8_GGML_BACKEND_H\n'
BACKEND_CPP_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend.cpp\n//\n// G12A/G13A/G14B: minimal ggml_backend_t wrapper/probe for CUDA8.\n//\n// This checkout\'s ggml_backend_i has graph callbacks but does not expose\n// get_default_buffer_type. Default buffer type remains available through the\n// local helper ggml_cuda8_ggml_backend_get_default_buffer_type().\n//\n// G14B adds compile-checked real ggml_backend_i graph callback stubs matching\n// this checkout\'s ggml-backend-impl.h signatures. These callbacks are safe\n// no-op/success stubs. Real graph execution remains in the G13 helper path.\n\n#include "ggml-cuda8-ggml-backend.h"\n#include "ggml-cuda8-ggml-buffer.h"\n#include "ggml-cuda8-dispatch.h"\n#include "ggml-backend-impl.h"\n\n#include <cstdio>\n#include <cstdlib>\n#include <cstring>\n\nstruct ggml_cuda8_ggml_backend_context {\n    int device;\n};\n\nstatic const char * cuda8_backend_get_name(ggml_backend_t backend) {\n    (void) backend;\n    return "CUDA8";\n}\n\nstatic void cuda8_backend_free(ggml_backend_t backend) {\n    if (backend == NULL) return;\n    ggml_cuda8_ggml_backend_context * ctx = (ggml_cuda8_ggml_backend_context *) backend->context;\n    if (ctx != NULL) std::free(ctx);\n    std::free(backend);\n}\n\nstatic void cuda8_backend_synchronize(ggml_backend_t backend) {\n    (void) backend;\n    std::printf("ggml-cuda8/backend: synchronize stub PASS\\n");\n}\n\nstatic ggml_backend_graph_plan_t cuda8_backend_graph_plan_create(ggml_backend_t backend, const struct ggml_cgraph * cgraph) {\n    (void) backend;\n    (void) cgraph;\n    std::printf("ggml-cuda8/backend: graph_plan_create stub PASS\\n");\n    return NULL;\n}\n\nstatic void cuda8_backend_graph_plan_free(ggml_backend_t backend, ggml_backend_graph_plan_t plan) {\n    (void) backend;\n    (void) plan;\n    std::printf("ggml-cuda8/backend: graph_plan_free stub PASS\\n");\n}\n\nstatic void cuda8_backend_graph_plan_update(ggml_backend_t backend, ggml_backend_graph_plan_t plan, const struct ggml_cgraph * cgraph) {\n    (void) backend;\n    (void) plan;\n    (void) cgraph;\n    std::printf("ggml-cuda8/backend: graph_plan_update stub PASS\\n");\n}\n\nstatic enum ggml_status cuda8_backend_graph_plan_compute(ggml_backend_t backend, ggml_backend_graph_plan_t plan) {\n    (void) backend;\n    (void) plan;\n    std::printf("ggml-cuda8/backend: graph_plan_compute stub PASS\\n");\n    return GGML_STATUS_SUCCESS;\n}\n\nstatic enum ggml_status cuda8_backend_graph_compute(ggml_backend_t backend, struct ggml_cgraph * cgraph) {\n    (void) backend;\n    (void) cgraph;\n    std::printf("ggml-cuda8/backend: graph_compute stub PASS\\n");\n    return GGML_STATUS_SUCCESS;\n}\n\nstatic void cuda8_backend_graph_optimize(ggml_backend_t backend, struct ggml_cgraph * cgraph) {\n    (void) backend;\n    (void) cgraph;\n    std::printf("ggml-cuda8/backend: graph_optimize stub PASS\\n");\n}\n\nstatic struct ggml_backend_i cuda8_backend_i;\nstatic bool cuda8_backend_i_initialized = false;\n\nstatic void cuda8_backend_iface_init(void) {\n    if (cuda8_backend_i_initialized) return;\n    std::memset(&cuda8_backend_i, 0, sizeof(cuda8_backend_i));\n\n    cuda8_backend_i.get_name = cuda8_backend_get_name;\n    cuda8_backend_i.free = cuda8_backend_free;\n\n    // Optional async/tensor callbacks remain NULL for now.\n    cuda8_backend_i.synchronize = cuda8_backend_synchronize;\n\n    // G14B: real ggml_backend_i graph callback stubs matching this checkout.\n    cuda8_backend_i.graph_plan_create = cuda8_backend_graph_plan_create;\n    cuda8_backend_i.graph_plan_free = cuda8_backend_graph_plan_free;\n    cuda8_backend_i.graph_plan_update = cuda8_backend_graph_plan_update;\n    cuda8_backend_i.graph_plan_compute = cuda8_backend_graph_plan_compute;\n    cuda8_backend_i.graph_compute = cuda8_backend_graph_compute;\n    cuda8_backend_i.graph_optimize = cuda8_backend_graph_optimize;\n\n    cuda8_backend_i_initialized = true;\n}\n\nextern "C" ggml_backend_t ggml_cuda8_ggml_backend_init(int device) {\n    cuda8_backend_iface_init();\n\n    ggml_cuda8_ggml_backend_context * ctx =\n        (ggml_cuda8_ggml_backend_context *) std::malloc(sizeof(ggml_cuda8_ggml_backend_context));\n    if (ctx == NULL) return NULL;\n    ctx->device = device;\n\n    ggml_backend_t backend = (ggml_backend_t) std::malloc(sizeof(struct ggml_backend));\n    if (backend == NULL) {\n        std::free(ctx);\n        return NULL;\n    }\n\n    std::memset(backend, 0, sizeof(*backend));\n    backend->iface = cuda8_backend_i;\n    backend->context = ctx;\n    return backend;\n}\n\nextern "C" int ggml_cuda8_ggml_backend_is_cuda8(ggml_backend_t backend) {\n    if (backend == NULL || backend->iface.get_name == NULL) return 0;\n    const char * name = backend->iface.get_name(backend);\n    return name != NULL && std::strcmp(name, "CUDA8") == 0;\n}\n\nextern "C" ggml_backend_buffer_type_t ggml_cuda8_ggml_backend_get_default_buffer_type(ggml_backend_t backend) {\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) return NULL;\n    return ggml_cuda8_ggml_buffer_type();\n}\n\nextern "C" int ggml_cuda8_ggml_backend_dispatch_op(\n    ggml_backend_t backend,\n    ggml_cuda8_context * ctx,\n    int op,\n    const ggml_tensor * src0,\n    const ggml_tensor * src1,\n    ggml_tensor * dst\n) {\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) {\n        std::fprintf(stderr, "ggml-cuda8/backend-dispatch: invalid backend\\n");\n        return -1;\n    }\n\n    if (ctx == NULL) {\n        std::fprintf(stderr, "ggml-cuda8/backend-dispatch: NULL CUDA8 context\\n");\n        return -1;\n    }\n\n    if (!ggml_cuda8_dispatch_supported(ctx, op, src0, src1, dst)) {\n        std::fprintf(stderr, "ggml-cuda8/backend-dispatch: unsupported op/layout op=%d\\n", op);\n        return -1;\n    }\n\n    return ggml_cuda8_dispatch_execute(ctx, op, src0, src1, dst);\n}\n'
PROBE_TEXT = '// ggml/src/ggml-cuda8/ggml-cuda8-ggml-backend-graph-api-probe.cpp\n//\n// G14B smoke: compile-checked real ggml_backend_i graph callback stubs.\n//\n// Validates that CUDA8 backend populates actual graph callback fields matching\n// this checkout\'s ggml-backend-impl.h signatures:\n//   graph_plan_create\n//   graph_plan_free\n//   graph_plan_update\n//   graph_plan_compute\n//   graph_compute\n//   graph_optimize\n//\n// This is intentionally not real graph execution yet. It is an ABI/API-shape\n// probe that calls the safe no-op/success stubs with NULL graph/plan inputs.\n\n#include "ggml-cuda8-ggml-backend.h"\n\n#include "ggml.h"\n#include "ggml-backend.h"\n#include "ggml-backend-impl.h"\n\n#include <cstdio>\n\nstatic int require_ptr(const char * name, const void * ptr) {\n    if (ptr == NULL) {\n        std::fprintf(stderr, "%s is NULL\\n", name);\n        return 1;\n    }\n    std::printf("%s present PASS\\n", name);\n    return 0;\n}\n\nint main(int argc, char ** argv) {\n    (void) argc;\n    (void) argv;\n\n    std::printf("ggml-cuda8-ggml-backend-graph-api-probe: starting\\n");\n\n    ggml_backend_t backend = ggml_cuda8_ggml_backend_init(0);\n    if (backend == NULL) {\n        std::fprintf(stderr, "backend init failed\\n");\n        return 1;\n    }\n\n    if (!ggml_cuda8_ggml_backend_is_cuda8(backend)) {\n        std::fprintf(stderr, "backend identity check failed\\n");\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    std::printf("backend name: %s\\n", backend->iface.get_name(backend));\n\n    int missing = 0;\n    missing += require_ptr("graph_plan_create", (const void *) backend->iface.graph_plan_create);\n    missing += require_ptr("graph_plan_free", (const void *) backend->iface.graph_plan_free);\n    missing += require_ptr("graph_plan_update", (const void *) backend->iface.graph_plan_update);\n    missing += require_ptr("graph_plan_compute", (const void *) backend->iface.graph_plan_compute);\n    missing += require_ptr("graph_compute", (const void *) backend->iface.graph_compute);\n    missing += require_ptr("graph_optimize", (const void *) backend->iface.graph_optimize);\n    missing += require_ptr("synchronize", (const void *) backend->iface.synchronize);\n\n    if (missing != 0) {\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    std::printf("calling graph callback stubs with NULL graph/plan inputs\\n");\n\n    ggml_backend_graph_plan_t plan = backend->iface.graph_plan_create(backend, NULL);\n    backend->iface.graph_plan_update(backend, plan, NULL);\n\n    enum ggml_status st_plan = backend->iface.graph_plan_compute(backend, plan);\n    if (st_plan != GGML_STATUS_SUCCESS) {\n        std::fprintf(stderr, "graph_plan_compute returned %d\\n", (int) st_plan);\n        backend->iface.graph_plan_free(backend, plan);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    enum ggml_status st_graph = backend->iface.graph_compute(backend, NULL);\n    if (st_graph != GGML_STATUS_SUCCESS) {\n        std::fprintf(stderr, "graph_compute returned %d\\n", (int) st_graph);\n        backend->iface.graph_plan_free(backend, plan);\n        backend->iface.free(backend);\n        return 1;\n    }\n\n    backend->iface.graph_optimize(backend, NULL);\n    backend->iface.synchronize(backend);\n    backend->iface.graph_plan_free(backend, plan);\n\n    backend->iface.free(backend);\n\n    std::printf("ggml-cuda8-ggml-backend-graph-api-probe: SUCCESS\\n");\n    return 0;\n}\n'
CMAKE_TARGET = "\n# ---------------------------------------------------------------------------\n# G14B real ggml_backend_i graph API shape probe:\n#   - populates graph callback stubs matching this checkout's interface\n#   - calls safe no-op/success graph callbacks directly\n# ---------------------------------------------------------------------------\n\ncuda_add_executable(ggml-cuda8-ggml-backend-graph-api-probe\n    ggml-cuda8-ggml-backend-graph-api-probe.cpp\n)\n\ntarget_link_libraries(ggml-cuda8-ggml-backend-graph-api-probe\n    ggml-cuda8-kernels\n    ${CUDA_LIBRARIES}\n)\n"

def backup(path):
    if os.path.exists(path):
        b = path + ".g14b-backup-" + str(int(time.time()))
        with open(path, "r") as f:
            data = f.read()
        with open(b, "w") as f:
            f.write(data)
        print("backup", b)

def write(path, text):
    backup(path)
    with open(path, "w") as f:
        f.write(text)
    print("wrote", path)

write(BACKEND_H, BACKEND_H_TEXT)
write(BACKEND_CPP, BACKEND_CPP_TEXT)
write(PROBE_CPP, PROBE_TEXT)
backup(CMAKE)
with open(CMAKE, "r") as f:
    cm = f.read()
if "ggml-cuda8-ggml-backend-graph-api-probe" not in cm:
    if not cm.endswith("\n"):
        cm += "\n"
    cm += CMAKE_TARGET
    with open(CMAKE, "w") as f:
        f.write(cm)
    print("patched", CMAKE)
else:
    print("CMake target already present")
print("")
print("G14B writer complete.")
